solution:
const logs = []
const user = new Proxy({ name: "Hariom", age: 25 }, {
  get(target, prop) {
    logs.push("Accessed: " + prop)
    return target[prop]
  }
})
const name = user.name
const age = user.age
return { name, age, logs }
